var palettes = {
  "Vibrant Tones": "#f94144, #f3722c, #f8961e, #f9844a, #f9c74f, #90be6d, #43aa8b, #4d908e, #577590, #277da1",
  "Vibrant Citrus Burst": "#f56a00, #fa8b01, #ffad03, #ffc243, #ffcf70, #cea7ee, #b67be6, #9d4edd, #72369d, #461e5c",
  "Deep Sea Green Glow": "#0466c8, #0353a4, #023e7d, #002855, #001845, #001233, #38b000, #70e000, #9ef01a, #ccff33",
  "Ocean Sunset Bonfire": "#8ecae6, #219ebc, #126782, #023047, #ffb703, #fd9e02, #fb8500, #bb3e03, #ae2012, #9b2226",
  "Neon Paradise Pop": "#f72585, #b5179e, #7209b7, #560bad, #480ca8, #3a0ca3, #159f91, #1bccba, #1ee3cf, #92f2e8",
  "Magical Lavender Haze": "#5d36e7, #6e44ff, #936bff, #b892ff, #dcaaf1, #ffc2e2, #ffa9cb, #ff90b3, #f7859c, #ef7a85"
}
var palette = [];
var progRate = 0.001;
var transitionFrames = 60;
var bg;
var w, s;
var masks = [];
var t = 0;
var maxRot;
var desync = true;
var showWonkSquares = true;
var noiseZoom = 10;

OPC.toggle({
  name: 'showWonkSquares',
  value: true,
  label: "Show Wonk Squares?",
  description: "Makes the background more interesting"
})

function parameterChanged(parameterName){
  if(parameterName === 'showWonkSquares'){
    showWonkSquares = !showWonkSquares;
    setup();
  }
}

function setup() {
  createCanvas(max(windowWidth, windowHeight), max(windowWidth, windowHeight));

  palette = random(Object.values(palettes)).split(", ");
  w = sqrt(2)*width; // the background graphic needs to be as wide as the diagonal of the canvas
  s = w/palette.length;
  pixelDensity(1);
  maxRot = TWO_PI;

  rectMode(CENTER);
  imageMode(CENTER);

  bg = getBackground();
  for(let i = 0; i < 10; i++){
    masks.push( {
      mask: maskCircle(bg, w*(1 - i/10)),
      a: random(TWO_PI),
      offset: random(10000), 
      'show': function() { 
        push();
        translate(width/2, height/2);
        rotate(this.a);       
        image(this.mask, 0,0);
        pop();
      },
      'update': function(){
        this.a = map(noise(this.offset, frameCount * progRate), 0, 1, 0, maxRot);
      }
    });
  }

}


function draw() {
  background(0);
  image(bg, width/2, height/2, w, w);
  syncBiz();
  for(let m of masks){
    m.update();
    m.show();
  }
}

function getBackground(){
  let newBG = createGraphics(w, w);
  newBG.rectMode(CENTER);
  newBG.noStroke();
  // draw bg of squares
  for(let i = 0; i < palette.length; i++){
    for(let j = 0; j < palette.length; j++){
      let x = (i + 0.5)*s;
      let y = (j + 0.5)*s;
      newBG.fill(random(palette));
      newBG.square(x, y, s);
      let squares = floor(random(3,8));
      let res = floor(random(5,11));
      let baseCol = random(palette);
      if(showWonkSquares) drawWonkSquareStack(squares, x, y, newBG, res, baseCol);
    }
  }

  return newBG.get();  // This converts p5.Graphics to p5.Image
}

function drawWonkSquareStack(squares, x, y, cnv, res, baseCol){
  let prevCol = baseCol;
  for(let k = 0; k < squares; k++){
        let colour = random(palette.filter(e => e !== prevCol)); // ensures different square cols every time
        wonkSquare(s*0.8 - s*k/(squares-1), x, y, cnv, res, colour);
      }
}

function wonkSquare(squareWidth, cx, cy, cnv, res, colour){
  let corners = [
    createVector(cx - squareWidth/2, cy - squareWidth/2), // tl
    createVector(cx + squareWidth/2, cy - squareWidth/2), // tr
    createVector(cx + squareWidth/2, cy + squareWidth/2), // br
    createVector(cx - squareWidth/2, cy + squareWidth/2), // bl
  ]

  // Add some randomness to the corners
  for(let corner of corners){
    corner.x += random(-0.25*squareWidth/res, -0.25*squareWidth/res);
    corner.y += random(-0.25*squareWidth/res, 0.25*squareWidth/res);
  }

  cnv.fill(colour);
  cnv.stroke(0);
  cnv.strokeWeight(2);
  cnv.beginShape();

  // Loop through each edge
  for(let i = 0; i < 4; i++){
    let c1 = corners[i];
    let c2 = corners[(i+1)%4];

    // Add vertices along this edge (including the starting corner)
    for(let j = 0; j <= res; j++){
      let c = p5.Vector.lerp(c1, c2, j/res);
      cnv.vertex(
        c.x + noise(c.x/noiseZoom, c.y/noiseZoom)*0.5*squareWidth/res, 
        c.y + noise(c.x/noiseZoom + 1000, c.y/noiseZoom)*0.5*squareWidth/res
      );
    }
  }

  cnv.endShape(CLOSE);
}


function maskCircle(img, diameter) {
  let clonedImg = img.get();
  let maskGraphics = createGraphics(img.width, img.height);

  maskGraphics.fill(255);
  maskGraphics.noStroke();
  maskGraphics.circle(img.width/2, img.height/2, diameter);

  clonedImg.mask(maskGraphics);

  return clonedImg;
}

// from easings.net
function easeInOutElastic(x){
var c5 = (2 * Math.PI) / 4.5;

return x === 0
  ? 0
  : x === 1
  ? 1
  : x < 0.5
  ? -(pow(2, 20 * x - 10) * sin((20 * x - 11.125) * c5)) / 2
  : (pow(2, -20 * x + 10) * sin((20 * x - 11.125) * c5)) / 2 + 1;
}

function mousePressed(){
  desync = !desync;
  t = 0;
  // console.log(`Desync: ${desync}, t: ${t}`);
}

function syncBiz(){
  t = constrain(t + 1/transitionFrames, 0, 1);
  let prog = easeInOutElastic(t);
  maxRot = desync ? prog*TWO_PI : TWO_PI*(1-prog);
}
